import{z as o,x as A,o as e,c as d,q as i,j as l,D as E,d as t,s as B,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"动态规划与再平衡","description":"","frontmatter":{"title":"动态规划与再平衡","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dynamic-programming-rebalance.md","filePath":"quant/dynamic-programming-rebalance.md","lastUpdated":1791413859000}'),p={name:"quant/dynamic-programming-rebalance.md"};function m(h,a,c,D,u,C){const r=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="动态规划与再平衡" tabindex="-1">动态规划与再平衡 <a class="header-anchor" href="#动态规划与再平衡" aria-label="Permalink to &quot;动态规划与再平衡&quot;">​</a></h1><div class="epigraph"><p>离散再平衡把连续 Merton 政策变成带费用的停时问题：不是每期都调到目标，而是等偏离足够大再动。</p><footer>—— 动态规划见 Bellman；带交易费用的组合见 Constantinides, Capital Market Equilibrium with Transaction Costs, JET, 1986</footer></div><p><a href="/quant/merton-portfolio-implementation">上一课</a>给出目标权重 \\(\\pi^\\ast\\)。缺口是<strong>时钟</strong>：连续再平衡在有费用时立刻不是最优。主干 <a href="/quant/rebalance-rules">再平衡规则</a> 已写日历/阈值启发式。本课把同一件事写成动态规划：状态、价值函数、无交易带。后课 Gârleanu–Pedersen 把冲击写成二次，给出另一种显式政策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无费用时，离散时间幂效用的最优仍接近 myopic 加对冲，每期把权重拉回 \\(\\pi^\\ast\\)。有与成交金额成正比的费用（或冲击）时，最优是：存在一个无交易区域，权重在带内不动，到边界才调回（或调到边界）。问题是把「季度再平衡」从运营习惯升级为对费用参数的解，否则阈值只是拍脑袋，与 <a href="/quant/net-edge">净边缘</a> 脱节。</p><p>状态至少包括：当前权重、财富、可选的预测状态。维度诅咒使完全 DP 只对低维可行；高维要用近似 DP、或二次冲击下的闭式（下一课）。</p><h3 id="无交易带不是风险预算带" tabindex="-1">无交易带不是风险预算带 <a class="header-anchor" href="#无交易带不是风险预算带" aria-label="Permalink to &quot;无交易带不是风险预算带&quot;">​</a></h3><p>风险预算说「偏离因子暴露不超过 x」。无交易带说「偏离目标权重直到费用被期望增益覆盖」。两者可以同向，但参数来源不同：一个来自跟踪误差限额，一个来自 \\(\\lambda_{\\mathrm{cost}}\\) 与信号衰减。混用会把风控限额当成最优再平衡。</p><p><span class="marginnote">T+1、涨跌停、最小手数把可行动作变成格点。DP 的动作空间必须是可执行动作，不能是连续 \\(w\\in\\mathbb{R}^n\\)。</span></p><p><span class="marginnote">无交易带可以类比冰箱温控：温度在设定区间内压缩机不启动，出了区间才制冷。频繁开关既费电又伤机器——组合同理，带内每笔小额调仓的费用就是那台被无谓启停的压缩机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 Bellman：\\(V_t(x)=\\max_a \\mathbb{E}[u(\\mathrm{cashflow})+V_{t+1}(x&#39;)]\\)，动作 \\(a\\) 含交易量。费用线性或固定+线性。解：低维用网格；高维用对无费用解加边界近似（Constantinides 的带）。校准费用用 TCA 的实现，不是用佣金表上的最低档。政策评估用同一模拟器比较：日历再平衡 vs 阈值 vs DP 近似，对象是扣费后的效用或增长率，不是周转率本身。</p><p><span class="marginnote">「Bellman 方程」翻译一下：它把「这一期怎么做最好」写成「本期即时效用 + 从下一期起一直按最优方式走的价值」。计算从最后一期倒着推回今天，每期只需做一个小决策——动态大问题就被拆成一串静态小问题。</span></p><p>DP 求解与政策评估如何闭环：</p>',14)),(e(),l(s,null,{default:E(()=>[B(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20S0%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E6%9D%83%E9%87%8D%E3%80%81%E8%B4%A2%E5%AF%8C%E3%80%81%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20BEL%5B%22Bellman%20%E5%80%92%E6%8E%A8%EF%BC%9A%E5%BD%93%E6%9C%9F%E6%95%88%E7%94%A8%E5%8A%A0%E5%90%8E%E7%BB%AD%E4%BB%B7%E5%80%BC%22%5D%0A%20%20COST%5B%22%E8%B4%B9%E7%94%A8%E5%8F%82%E6%95%B0%EF%BC%9A%E5%8F%96%20TCA%20%E5%AE%9E%E6%B5%8B%22%5D%20--%3E%20BEL%0A%20%20BEL%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%EF%BC%9A%E5%B8%A6%E5%86%85%E4%B8%8D%E5%8A%A8%EF%BC%8C%E5%87%BA%E7%95%8C%E8%B0%83%E5%9B%9E%22%5D%0A%20%20POL%20--%3E%20SIM%5B%22%E5%90%8C%E4%B8%80%E6%A8%A1%E6%8B%9F%E5%99%A8%E5%9B%9E%E6%94%BE%22%5D%0A%20%20CAL%5B%22%E6%97%A5%E5%8E%86%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20SIM%0A%20%20THR%5B%22%E9%98%88%E5%80%BC%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20SIM%0A%20%20SIM%20--%3E%20OBJ%5B%22%E6%AF%94%E8%BE%83%E6%89%A3%E8%B4%B9%E5%90%8E%E7%9A%84%E6%95%88%E7%94%A8%E6%88%96%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%0A%20%20OBJ%20--%3E%7C%22%E4%B8%8D%E8%BE%BE%E6%A0%87%EF%BC%9A%E8%B4%B9%E7%94%A8%E6%88%96%E5%B8%A6%E5%AE%BD%E9%9C%80%E9%87%8D%E6%A0%A1%22%7C%20BEL%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"再平衡的边际收益是把风险暴露拉回有效前沿（或拉回 Merton \\(\\pi\\)）所增加的期望效用；边际成本是费用加冲击加税（后课）。最优在二者相等的边界上。信号衰减快（高频 alpha）时带变窄，该多动；信号是风险溢价慢变量时带变宽。这与「永远保持目标权重」的运营话术冲突，却与容量课一致。",-1)),(e(),l(s,null,{default:E(()=>[B(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Pi%5B%22%E7%9B%AE%E6%A0%87%20%CF%80%20%E6%98%9F%22%5D%20--%3E%20Band%5B%22%E6%97%A0%E4%BA%A4%E6%98%93%E5%B8%A6%22%5D%0A%20%20Cost%5B%22%E8%B4%B9%E7%94%A8%E4%B8%8E%E5%86%B2%E5%87%BB%22%5D%20--%3E%20Band%0A%20%20Decay%5B%22%E4%BF%A1%E5%8F%B7%E8%A1%B0%E5%87%8F%E9%80%9F%E5%BA%A6%22%5D%20--%3E%20Band%0A%20%20Band%20--%3E%20Act%5B%22%E5%87%BA%E7%95%8C%E6%89%8D%E4%BA%A4%E6%98%93%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>估计的 \\(\\pi^\\ast\\) 本身在动（校准噪声），带会被噪声触发，需要把 \\(\\pi^\\ast\\) 也平滑，见正则化课的隔日罚精神。多账户、税基批次让状态爆炸，税务课再加。DP 对模型误设敏感：费用低估会交易过度。</p><p><span class="marginnote">费用低估的后果代个数：真实单边费用 15bp 而校准用了 5bp，DP 会给出过窄的带，换手频率翻倍不止，多付的周转成本直接从信号增益里扣。DP 的输出只对输入的费用参数负责——费用错了，带就错了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有费用时最优是无交易带，不是每期精确再平衡。</li><li>带的宽度由费用与信号衰减共同决定，不是由日历。</li><li>高维求近似；可执行约束必须进动作空间。</li><li>出处：Bellman 动态规划；Constantinides, <em>JET</em>, 1986。</li></ul>',5))])}const f=o(p,[["render",m]]);export{_ as __pageData,f as default};
